-- Expand: a plan's attachment may be a WebM an agent recorded, held to a video's 4 MB bound rather than a picture's. The check only widens, so every row standing passes it.
ALTER TABLE "attachment" DROP CONSTRAINT "attachment_bytes_bound", ADD CONSTRAINT "attachment_bytes_bound" CHECK (("chat_message_id" is null or octet_length("bytes") <= 1500000 or ("content_type" = 'video/webm' and octet_length("bytes") <= 4000000)) and ("conversation_id" is null or octet_length("bytes") <= 4000000) and (not ("task_id" is not null and num_nonnulls("chat_message_id", "inbox_item_id", "conversation_id", "plan_comment_id") = 0) or octet_length("bytes") <= 1500000 or ("content_type" = 'video/webm' and octet_length("bytes") <= 4000000)));